// Local fallback output
const geometry = new THREE.BoxGeometry(1, 1, 1);
const material = new THREE.MeshStandardMaterial({ color: 0x1d8cf8, metalness: 0.8, roughness: 0.2 });
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);
function animate() {
  requestAnimationFrame(animate);
  mesh.rotation.x += 0.01;
  mesh.rotation.y += 0.01;
  renderer.render(scene, camera);
}
animate();

const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(10, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.8;
floor.receiveShadow = true;
scene.add(floor);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const boxSize = 1.2;
const mainGeometry = new THREE.BoxGeometry(boxSize, boxSize, boxSize);
const mainMaterial = new THREE.MeshStandardMaterial({ 
  color: 0x1d8cf8, 
  metalness: 0.7, 
  roughness: 0.15,
  clearcoat: 0.8,
  clearcoatRoughness: 0.1
});
const mainCube = new THREE.Mesh(mainGeometry, mainMaterial);
mainCube.castShadow = true;
mainCube.receiveShadow = true;
heroGroup.add(mainCube);

const coreGeometry = new THREE.BoxGeometry(boxSize * 0.6, boxSize * 0.6, boxSize * 0.6);
const coreMaterial = new THREE.MeshStandardMaterial({ 
  color: 0x0f6bd0, 
  metalness: 0.9, 
  roughness: 0.05,
  emissive: 0x0f6bd0,
  emissiveIntensity: 0.2
});
const coreCube = new THREE.Mesh(coreGeometry, coreMaterial);
heroGroup.add(coreCube);

const frameGeometry = new THREE.BoxGeometry(boxSize * 1.15, boxSize * 1.15, boxSize * 1.15);
const edges = new THREE.EdgesGeometry(frameGeometry);
const frameMaterial = new THREE.LineBasicMaterial({ color: 0xaad6ff, transparent: true, opacity: 0.4 });
const frame = new THREE.LineSegments(edges, frameMaterial);
heroGroup.add(frame);

const particleCount = 32;
const particleGeometry = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount * 3; i += 3) {
  positions[i] = (Math.random() - 0.5) * 4;
  positions[i+1] = (Math.random() - 0.5) * 4;
  positions[i+2] = (Math.random() - 0.5) * 4;
}
particleGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
const particleMaterial = new THREE.PointsMaterial({ 
  color: 0x5a9fd4, 
  size: 0.05, 
  transparent: true, 
  opacity: 0.6 
});
const particles = new THREE.Points(particleGeometry, particleMaterial);
heroGroup.add(particles);

camera.position.set(4.4, 2.4, 5.2);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  heroGroup.rotation.y = t * 0.18;
  heroGroup.rotation.x = Math.sin(t * 0.3) * 0.08;
  heroGroup.position.y = Math.sin(t * 0.8) * 0.15;

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  frame.material.opacity = 0.3 + Math.sin(t * 2) * 0.1;
  particles.rotation.y = t * 0.05;

  controls.update();
  renderer.render(scene, camera);
}
animate();

